NTSTATUS cli_cm_force_encryption(struct cli_state *c, /* <=== cli_cm_force_encryption */ 
			const char *username,
			const char *password,
			const char *domain,
			const char *sharename)
{
	NTSTATUS status;

	if (smbXcli_conn_protocol(c->conn) >= PROTOCOL_SMB2_02) {
		status = smb2cli_session_encryption_on(c->smb2.session);
		if (NT_STATUS_EQUAL(status,NT_STATUS_NOT_SUPPORTED)) {
			d_printf("Encryption required and "
				"server doesn't support "
				"SMB3 encryption - failing connect\n");
		} else if (!NT_STATUS_IS_OK(status)) {
			d_printf("Encryption required and "
				"setup failed with error %s.\n",
				nt_errstr(status));
		}
		return status;
	}

	status = cli_force_encryption(c,
					username,
					password,
					domain);

	if (NT_STATUS_EQUAL(status,NT_STATUS_NOT_SUPPORTED)) {
		d_printf("Encryption required and "
			"server that doesn't support "
			"UNIX extensions - failing connect\n");
	} else if (NT_STATUS_EQUAL(status,NT_STATUS_UNKNOWN_REVISION)) {
		d_printf("Encryption required and "
			"can't get UNIX CIFS extensions "
			"version from server.\n");
	} else if (NT_STATUS_EQUAL(status,NT_STATUS_UNSUPPORTED_COMPRESSION)) {
		d_printf("Encryption required and "
			"share %s doesn't support "
			"encryption.\n", sharename);
	} else if (!NT_STATUS_IS_OK(status)) {
		d_printf("Encryption required and "
			"setup failed with error %s.\n",
			nt_errstr(status));
	}

	return status;
}

static bool do_connect(struct smbclient_context *ctx,  /* <=== do_connect */ 
		       struct tevent_context *ev_ctx,
		       struct resolve_context *resolve_ctx,
		       const char *specified_server, const char **ports, 
		       const char *specified_share, 
			   const char *socket_options,
		       struct cli_credentials *cred, 
		       struct smbcli_options *options,
		       struct smbcli_session_options *session_options,
			   struct gensec_settings *gensec_settings)
{
	NTSTATUS status;
	char *server, *share;

	rl_ctx = ctx; /* Ugly hack */

	if (strncmp(specified_share, "\\\\", 2) == 0 ||
	    strncmp(specified_share, "//", 2) == 0) {
		bool ok;

		ok = smbcli_parse_unc(specified_share, ctx, &server, &share);
		if (!ok) {
			d_printf("Failed to parse UNC\n");
			talloc_free(ctx);
			return false;
		}
	} else {
		share = talloc_strdup(ctx, specified_share);
		server = talloc_strdup(ctx, specified_server);
		if (share == NULL || server == NULL) {
			d_printf("Failed to allocate memory for server and share\n");
			talloc_free(ctx);
			return false;
		}
	}

	ctx->remote_cur_dir = talloc_strdup(ctx, "\\");
	if (ctx->remote_cur_dir == NULL) {
		talloc_free(ctx);
		return false;
	}

	status = smbcli_full_connection(ctx, &ctx->cli, server, ports,
					share, NULL, 
					socket_options,
					cred, resolve_ctx, 
					ev_ctx, options, session_options,
					gensec_settings);
	if (!NT_STATUS_IS_OK(status)) {
		d_printf("Connection to \\\\%s\\%s failed - %s\n", 
			 server, share, nt_errstr(status));
		talloc_free(ctx);
		return false;
	}

	return true;
}

